(window.KOTOBA_HK=window.KOTOBA_HK||{})[25]={"n":25,"S":[{"id":"l25a","ti":[[["塩","しお"],["を","を"],["ひく","ひく","ひく",5],["不思議な","ふしぎな","不思議",1],["石臼","いしうす"]]],"tt":{"az":"Duz üyüdən sehrli daş dəyirman","en":"The Magic Mill That Grinds Salt","ru":"Волшебная мельница, которая мелет соль"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["海","うみ"],["の","の"],["近く","ちかく"],["の","の"],["田舎","いなか"],["に","に"],["、"],["貧しい","まずしい"],["兄","あに"],["と","と"],["お金持ち","おかねもち"],["の","の"],["弟","おとうと"],["が","が"],["住んでいました","すんでいました","住む",31],["。"],["兄","あに"],["は","は"],["毎日","まいにち"],["がんばって","がんばって","がんばって",3],["働きました","はたらきました","働く",2],["が","が"],["、"],["お金","おかね"],["が","が"],["足りませんでした","たりませんでした","足りませんでした",4],["。"],["ある日","あるひ"],["、"],["兄","あに"],["は","は"],["山","やま"],["で","で"],["小さな","ちいさな"],["おじいさん","おじいさん"],["に","に"],["会いました","あいました","会う",2],["。"],["おじいさん","おじいさん"],["は","は"],["兄","あに"],["に","に"],["不思議な","ふしぎな","不思議",1],["石臼","いしうす"],["を","を"],["くれました","くれました","くれました",2],["。"]]],"tr":{"az":"Qədim zamanlarda dəniz yaxınlığındakı bir kənddə kasıb böyük qardaşla varlı kiçik qardaş yaşayırdı. Böyük qardaş hər gün çox çalışırdı, amma pulu çatmırdı. Bir gün dağda balaca bir qoca ilə rastlaşdı. Qoca ona sehrli bir daş dəyirman verdi.","en":"Long, long ago, a poor older brother and a rich younger brother lived in a village near the sea. The older brother worked hard every day, but he never had enough money. One day, he met a little old man in the mountains. The old man gave him a magic stone mill.","ru":"Давным-давно в деревне у моря жили бедный старший брат и богатый младший брат. Старший брат каждый день усердно работал, но денег ему не хватало. Однажды в горах он встретил маленького старичка. Старичок подарил ему волшебную каменную мельницу."}},{"t":[[["おじいさん","おじいさん"],["は","は"],["「"],["右","みぎ"],["に","に"],["回したら","まわしたら","回したら",44],["、"],["ほしい","ほしい"],["物","もの"],["が","が"],["出ます","でます","出る",11],["。"],["止める","とめる","止める",5],["とき","とき"],["は","は"],["、"],["左","ひだり"],["に","に"],["回してください","まわしてください","回してください",35],["」"],["と","と"],["説明","せつめい"],["しました","しました","する",2],["。"],["兄","あに"],["が","が"],["家","いえ"],["に","に"],["帰ったら","かえったら","帰る",44],["、"],["もう","もう"],["夜","よる"],["でした","でした","です",9],["。"],["兄","あに"],["は","は"],["「"],["お米","おこめ"],["が","が"],["ほしい","ほしい"],["」"],["と","と"],["言って","いって","言う",3],["、"],["石臼","いしうす"],["を","を"],["右","みぎ"],["に","に"],["回しました","まわしました","回しました",2],["。"],["する","する","する",5],["と","と"],["、"],["白い","しろい"],["お米","おこめ"],["が","が"],["たくさん","たくさん"],["出ました","でました","出る",2],["。"]]],"tr":{"az":"Qoca izah etdi: «Sağa çevirsən, istədiyin şey çıxacaq. Dayandırmaq istəyəndə sola çevir». Böyük qardaş evə qayıdanda artıq gecə idi. O, «Düyü istəyirəm» deyib dəyirmanı sağa çevirdi. Bu zaman içindən çoxlu ağ düyü töküldü.","en":"The old man explained, “If you turn it to the right, it will produce whatever you want. When you want to stop it, turn it to the left.” By the time the older brother got home, it was already night. He said, “I want rice,” and turned the mill to the right. Then lots of white rice came out.","ru":"Старичок объяснил: «Если повернёшь её вправо, появится всё, что пожелаешь. Чтобы остановить её, поверни влево». Когда старший брат вернулся домой, была уже ночь. Он сказал: «Хочу риса» и повернул мельницу вправо. И тут из неё посыпалось много белого риса."}},{"t":[[["兄","あに"],["は","は"],["石臼","いしうす"],["を","を"],["左","ひだり"],["に","に"],["回して","まわして","回して",3],["、"],["止めました","とめました","止める",2],["。"],["それから","それから"],["、"],["食べ物","たべもの"],["や","や"],["服","ふく"],["も","も"],["出しました","だしました","出す",2],["。"],["お金持ち","おかねもち"],["に","に"],["なっても","なっても","なる",34],["、"],["兄","あに"],["は","は"],["親切","しんせつ"],["でした","でした","です",9],["。"],["村","むら"],["の","の"],["人","ひと"],["が","が"],["おなか","おなか"],["を","を"],["すかせたら","すかせたら","すく",50],["、"],["食べ物","たべもの"],["を","を"],["あげました","あげました","あげる",2],["。"],["みんな","みんな"],["は","は"],["とても","とても"],["喜びました","よろこびました","喜ぶ",2],["。"]]],"tr":{"az":"Böyük qardaş dəyirmanı sola çevirib dayandırdı. Sonra yemək və paltar da əldə etdi. Varlansa da, mehribanlığını itirmədi. Kənddə kimsə acanda ona yemək verirdi. Hamı çox sevinirdi.","en":"The older brother turned the mill to the left and stopped it. Then he made food and clothes too. Even after becoming rich, he remained kind. Whenever someone in the village was hungry, he gave them food. Everyone was very happy.","ru":"Старший брат повернул мельницу влево и остановил её. Потом он получил ещё еду и одежду. Даже разбогатев, он остался добрым. Когда кто-нибудь в деревне голодал, он давал ему еду. Все очень радовались."}},{"t":[[["弟","おとうと"],["は","は"],["その","その"],["話","はなし"],["を","を"],["聞いて","きいて","聞く",3],["、"],["石臼","いしうす"],["が","が"],["ほしく","ほしく"],["なりました","なりました","なる",2],["。"],["「"],["もし","もし"],["石臼","いしうす"],["を","を"],["もらったら","もらったら","もらう",44],["、"],["億","おく"],["の","の"],["お金","おかね"],["を","を"],["作ろう","つくろう","作る",7],["」"],["と","と"],["考えました","かんがえました","考える",2],["。"],["ある","ある","ある(連体詞)"],["夜","よる"],["、"],["弟","おとうと"],["は","は"],["兄","あに"],["の","の"],["家","いえ"],["に","に"],["入り","はいり","入る",10],["、"],["石臼","いしうす"],["を","を"],["取りました","とりました","取る",2],["。"],["でも","でも"],["、"],["止め方","とめかた"],["は","は"],["知りませんでした","しりませんでした","知る",4],["。"]]],"tr":{"az":"Kiçik qardaş bu əhvalatı eşidəndə dəyirmanı özü üçün istədi. «Əgər dəyirmanı əldə etsəm, yüz milyonlarla pul qazanaram», deyə düşündü. Bir gecə böyük qardaşının evinə girib dəyirmanı götürdü. Amma onu necə dayandıracağını bilmirdi.","en":"When the younger brother heard about the mill, he wanted it for himself. “If I get that mill, I'll make hundreds of millions,” he thought. One night, he entered his older brother's house and took the mill. But he did not know how to stop it.","ru":"Услышав эту историю, младший брат захотел мельницу себе. «Если я получу эту мельницу, то сделаю сотни миллионов», подумал он. Однажды ночью он проник в дом старшего брата и забрал мельницу. Но он не знал, как её остановить."}},{"t":[[["弟","おとうと"],["は","は"],["石臼","いしうす"],["を","を"],["持って","もって","持つ",3],["、"],["船","ふね"],["で","で"],["海","うみ"],["へ","へ"],["出ました","でました","出る",2],["。"],["船","ふね"],["に","に"],["は","は"],["食べ物","たべもの"],["が","が"],["ありました","ありました","ある",2],["が","が"],["、"],["塩","しお"],["が","が"],["ありませんでした","ありませんでした","ある",4],["。"],["弟","おとうと"],["は","は"],["「"],["塩","しお"],["が","が"],["ほしい","ほしい"],["」"],["と","と"],["言って","いって","言う",3],["、"],["石臼","いしうす"],["を","を"],["右","みぎ"],["に","に"],["回しました","まわしました","回しました",2],["。"],["する","する","する",5],["と","と"],["、"],["白い","しろい"],["塩","しお"],["が","が"],["どんどん","どんどん"],["出ました","でました","出る",2],["。"]]],"tr":{"az":"Kiçik qardaş dəyirmanı götürüb qayıqla dənizə çıxdı. Qayıqda yemək vardı, amma duz yox idi. O, «Duz istəyirəm» deyib dəyirmanı sağa çevirdi. Bu zaman ağ duz dayanmadan tökülməyə başladı.","en":"The younger brother took the mill and sailed out to sea in a boat. There was food on the boat, but there was no salt. He said, “I want salt,” and turned the mill to the right. Then white salt began pouring out without stopping.","ru":"Младший брат взял мельницу и вышел в море на лодке. Еда на лодке была, но соли не было. Он сказал: «Хочу соли» и повернул мельницу вправо. И тут из неё без остановки начала сыпаться белая соль."}},{"t":[[["弟","おとうと"],["が","が"],["左","ひだり"],["に","に"],["回しても","まわしても","回しても",34],["、"],["石臼","いしうす"],["は","は"],["止まりませんでした","とまりませんでした","止まる",4],["。"],["弟","おとうと"],["は","は"],["本当","ほんとう"],["の","の"],["止め方","とめかた"],["を","を"],["知らなかった","しらなかった","知る",22],["の","の"],["です","です"],["。"],["塩","しお"],["が","が"],["多くても","おおくても","多い",34],["、"],["もう","もう"],["何","なん"],["も","も"],["できませんでした","できませんでした","できる",4],["。"],["船","ふね"],["は","は"],["だんだん","だんだん"],["重く","おもく","重い"],["なりました","なりました","なる",2],["。"],["弟","おとうと"],["は","は"],["「"],["助けて","たすけて","助ける",3],["！"],["」"],["と","と"],["大きな","おおきな"],["声","こえ"],["で","で"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Kiçik qardaş dəyirmanı sola çevirməyə çalışsa da, onu dayandıra bilmədi. Çünki dayandırmağın düzgün yolunu bilmirdi. Duz həddindən artıq çoxalmışdı və artıq heç nə edə bilmirdi. Qayıq getdikcə ağırlaşırdı. O, ucadan «Kömək edin!» deyə qışqırdı.","en":"Even when the younger brother tried turning it to the left, he could not stop the mill. He did not know the correct way to stop it. There was far too much salt, and he could do nothing. The boat became heavier and heavier. “Help!” he shouted loudly.","ru":"Хотя младший брат пытался повернуть мельницу влево, остановить её не получалось. Он не знал, как правильно это сделать. Соли стало слишком много, и он уже ничего не мог поделать. Лодка становилась всё тяжелее. «Помогите!» закричал он."}},{"t":[[["とうとう","とうとう"],["船","ふね"],["は","は"],["海","うみ"],["に","に"],["沈みました","しずみました","沈みました",2],["。"],["弟","おとうと"],["は","は"],["泳いで","およいで","泳ぐ",13],["、"],["近く","ちかく"],["の","の"],["島","しま"],["に","に"],["着きました","つきました","着きました",2],["。"],["でも","でも"],["、"],["石臼","いしうす"],["は","は"],["海","うみ"],["の","の"],["底","そこ"],["へ","へ"],["落ちました","おちました","落ちる",2],["。"],["弟","おとうと"],["は","は"],["泣きながら","なきながら","泣く",43],["、"],["「"],["お金","おかね"],["より","より"],["大切な","たいせつな","大切",1],["こと","こと"],["が","が"],["ありました","ありました","ある",2],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Nəhayət, qayıq dənizdə batdı. Kiçik qardaş üzərək yaxınlıqdakı adaya çatdı. Amma dəyirman dənizin dibinə düşdü. O, ağlaya-ağlaya «Puldan daha vacib şeylər var imiş», dedi.","en":"At last, the boat sank into the sea. The younger brother swam to a nearby island. But the mill fell to the bottom of the sea. Crying, he said, “There are things more important than money.”","ru":"Наконец лодка затонула. Младший брат доплыл до ближайшего острова. Но мельница упала на морское дно. Плача, он сказал: «Есть вещи важнее денег»."}},{"t":[[["海","うみ"],["の","の"],["底","そこ"],["で","で"],["は","は"],["、"],["今","いま"],["も","も"],["石臼","いしうす"],["が","が"],["塩","しお"],["を","を"],["出しています","だしています","出す",24],["。"],["魚","さかな"],["が","が"],["見ても","みても","見る",34],["、"],["たこ","たこ"],["が","が"],["触っても","さわっても","触る",34],["、"],["止まりません","とまりません","止まる",6],["。"],["海","うみ"],["の","の"],["水","みず"],["が","が"],["塩辛い","しおからい"],["の","の"],["は","は"],["、"],["その","その"],["石臼","いしうす"],["の","の"],["ため","ため"],["だ","だ","です"],["そう","そう"],["です","です"],["。"],["もし","もし"],["海","うみ"],["へ","へ"],["行ったら","いったら","行く",44],["、"],["波","なみ"],["の","の"],["音","おと"],["を","を"],["よく","よく"],["聞いてください","きいてください","聞く",35],["。"],["石臼","いしうす"],["の","の"],["音","おと"],["が","が"],["聞こえる","きこえる","聞こえる",5],["か","か"],["も","も"],["しれません","しれません","しれません",6],["。"]]],"tr":{"az":"Dənizin dibində dəyirman indi də duz tökür. Balıqlar ona baxsa da, səkkizayaqlı ona toxunsa da, dayanmır. Deyilənə görə, dəniz suyunun duzlu olmasının səbəbi həmin dəyirmandır. Əgər dənizə getsəniz, dalğaların səsinə diqqətlə qulaq asın. Bəlkə dəyirmanın səsini eşidəsiniz.","en":"Even now, the mill is producing salt at the bottom of the sea. Fish can stare at it and octopuses can touch it, but it never stops. People say that this mill is why seawater is salty. If you ever go to the sea, listen carefully to the waves. You might hear the sound of the mill.","ru":"Даже сейчас мельница производит соль на морском дне. Рыбы смотрят на неё, осьминоги трогают её, но она не останавливается. Говорят, именно поэтому морская вода солёная. Если когда-нибудь пойдёте к морю, внимательно послушайте шум волн. Возможно, вы услышите звук мельницы."}}]},{"id":"l25b","ti":[[["十年後","じゅうねんご"],["の","の"],["タイム","タイム"],["カプセル","カプセル"]]],"tt":{"az":"On il sonrakı zaman kapsulu","en":"The Time Capsule Ten Years Later","ru":"Капсула времени десять лет спустя"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["田舎","いなか"],["の","の"],["小学校","しょうがっこう"],["に","に"],["、"],["ハル","ハル"],["と","と"],["ソラ","ソラ"],["と","と"],["ミオ","ミオ"],["と","と"],["いう","いう","いう",5],["三人","さんにん"],["の","の"],["友達","ともだち"],["が","が"],["いました","いました","いる",2],["。"],["三人","さんにん"],["は","は"],["毎日","まいにち"],["いっしょ","いっしょ"],["に","に"],["遊びました","あそびました","遊ぶ",2],["。"],["ある日","あるひ"],["、"],["先生","せんせい"],["が","が"],["「"],["十年後","じゅうねんご"],["の","の"],["自分","じぶん"],["に","に"],["手紙","てがみ"],["を","を"],["書きましょう","かきましょう","書く",20],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["三人","さんにん"],["は","は"],["大きな","おおきな"],["箱","はこ"],["に","に"],["手紙","てがみ"],["を","を"],["入れました","いれました","入れる",2],["。"]]],"tr":{"az":"Bir kənd ibtidai məktəbində Haru, Sora və Mio adlı üç dost var idi. Onlar hər gün birlikdə oynayırdılar. Bir gün müəllim «Gəlin on il sonrakı özümüzə məktub yazaq», dedi. Üçü də məktublarını böyük bir qutuya qoydu.","en":"At a small elementary school in the countryside, there were three friends named Haru, Sora, and Mio. They played together every day. One day, their teacher said, “Let's write letters to ourselves ten years from now.” The three put their letters into a large box.","ru":"В одной деревенской начальной школе учились трое друзей: Хару, Сора и Мио. Каждый день они играли вместе. Однажды учитель сказал: «Давайте напишем письма себе через десять лет». Все трое положили свои письма в большую коробку."}},{"t":[[["ハル","ハル"],["は","は"],["「"],["大きく","おおきく","大きい"],["なったら","なったら","なる",44],["、"],["空","そら"],["を","を"],["飛ぶ","とぶ","飛ぶ",5],["ロボット","ロボット"],["を","を"],["作ります","つくります","作る",11],["」"],["と","と"],["書きました","かきました","書く",2],["。"],["ソラ","ソラ"],["は","は"],["「"],["チャンス","チャンス"],["が","が"],["あったら","あったら","ある",44],["、"],["外国","がいこく"],["へ","へ"],["留学","りゅうがく"],["します","します","する",11],["」"],["と","と"],["書きました","かきました","書く",2],["。"],["ミオ","ミオ"],["は","は"],["「"],["もし","もし"],["有名に","ゆうめいに","有名に",8],["なっても","なっても","なる",34],["、"],["友達","ともだち"],["を","を"],["忘れません","わすれません","忘れる",6],["」"],["と","と"],["書きました","かきました","書く",2],["。"],["三人","さんにん"],["は","は"],["箱","はこ"],["を","を"],["学校","がっこう"],["の","の"],["庭","にわ"],["に","に"],["埋めました","うめました","埋めました",2],["。"]]],"tr":{"az":"Haru yazdı: «Böyüyəndə uça bilən robot düzəldəcəyəm». Sora yazdı: «Fürsətim olsa, xaricdə təhsil alacağam». Mio isə yazdı: «Məşhur olsam da, dostlarımı unutmayacağam». Sonra üç dost qutunu məktəbin həyətində basdırdı.","en":"Haru wrote, “When I grow up, I'll build a robot that can fly.” Sora wrote, “If I get the chance, I'll study abroad.” Mio wrote, “Even if I become famous, I won't forget my friends.” Then the three buried the box in the schoolyard.","ru":"Хару написал: «Когда вырасту, создам летающего робота». Сора написал: «Если появится возможность, буду учиться за границей». А Мио написала: «Даже если стану знаменитой, не забуду друзей». Потом трое друзей закопали коробку во школьном дворе."}},{"t":[[["十年","じゅうねん"],["が","が"],["過ぎました","すぎました","過ぎました",2],["。"],["ハル","ハル"],["は","は"],["町","まち"],["で","で"],["ロボット","ロボット"],["を","を"],["研究","けんきゅう"],["していました","していました","する",15],["が","が"],["、"],["空","そら"],["を","を"],["飛ぶ","とぶ","飛ぶ",5],["ロボット","ロボット"],["は","は"],["まだ","まだ"],["できませんでした","できませんでした","できる",4],["。"],["ソラ","ソラ"],["は","は"],["外国","がいこく"],["に","に"],["留学","りゅうがく"],["して","して","する",3],["、"],["いろいろな","いろいろな","いろいろな",1],["こと","こと"],["を","を"],["勉強","べんきょう"],["しました","しました","する",2],["。"],["ミオ","ミオ"],["は","は"],["歌手","かしゅ"],["で","で"],["は","は"],["なく","なく","ない"],["、"],["小学校","しょうがっこう"],["の","の"],["先生","せんせい"],["に","に"],["なりました","なりました","なる",2],["。"]]],"tr":{"az":"On il keçdi. Haru şəhərdə robotlar üzərində araşdırma aparırdı, amma hələ uça bilən robot düzəldə bilməmişdi. Sora xaricdə təhsil almış, çox şey öyrənmişdi. Mio isə müğənni yox, ibtidai məktəb müəllimi olmuşdu.","en":"Ten years passed. Haru was studying robots in the city, but he still had not made a flying robot. Sora had studied abroad and learned many things. Mio had become an elementary school teacher instead of a singer.","ru":"Прошло десять лет. Хару занимался исследованиями роботов в городе, но летающего робота ещё не создал. Сора учился за границей и узнал много нового. А Мио стала не певицей, а учительницей начальной школы."}},{"t":[[["ある日","あるひ"],["、"],["ミオ","ミオ"],["が","が"],["二人","ふたり"],["に","に"],["電話","でんわ"],["しました","しました","する",2],["。"],["「"],["もしもし","もしもし"],["、"],["十年","じゅうねん"],["前","まえ"],["の","の"],["箱","はこ"],["を","を"],["覚えています","おぼえています","覚えています",24],["か","か"],["。"],["日曜","にちよう"],["日","ひ"],["に","に"],["学校","がっこう"],["へ","へ"],["来てください","きてください","来る",35],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"],["仕事","しごと"],["が","が"],["忙しくても","いそがしくても","忙しい",34],["、"],["行く","いく","行く",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"],["ソラ","ソラ"],["も","も"],["遠く","とおく"],["に","に"],["住んでいました","すんでいました","住む",31],["が","が"],["、"],["電車","でんしゃ"],["で","で"],["帰って来ました","かえってきました","帰る",2],["。"]]],"tr":{"az":"Bir gün Mio hər iki dostuna zəng etdi. «Alo, on il əvvəlki qutunu xatırlayırsınız? Bazar günü məktəbə gəlin», dedi. Haru işi çox olsa da, getməyə qərar verdi. Sora da uzaqda yaşayırdı, amma qatarla geri qayıtdı.","en":"One day, Mio called both friends. “Hello, do you remember the box from ten years ago? Please come to the school on Sunday,” she said. Even though Haru was busy with work, he decided to go. Sora lived far away too, but he returned by train.","ru":"Однажды Мио позвонила обоим друзьям. «Алло, помните коробку, которую мы закопали десять лет назад? Приходите в школу в воскресенье», сказала она. Хару решил приехать, хотя был занят работой. Сора тоже жил далеко, но вернулся на поезде."}},{"t":[[["日曜","にちよう"],["日","ひ"],["、"],["三人","さんにん"],["が","が"],["学校","がっこう"],["に","に"],["着いたら","ついたら","着いたら",44],["、"],["庭","にわ"],["に","に"],["大きな","おおきな"],["木","き"],["が","が"],["ありました","ありました","ある",2],["。"],["箱","はこ"],["は","は"],["その","その"],["木","き"],["の","の"],["下","した"],["に","に"],["ありました","ありました","ある",2],["。"],["三人","さんにん"],["は","は"],["土","つち"],["を","を"],["取って","とって","取る",3],["、"],["やっと","やっと"],["箱","はこ"],["を","を"],["見つけました","みつけました","見つける",2],["。"],["箱","はこ"],["を","を"],["開けたら","あけたら","開ける",44],["、"],["昔","むかし"],["の","の"],["手紙","てがみ"],["と","と"],["一枚","いちまい"],["の","の"],["写真","しゃしん"],["が","が"],["出てきました","でてきました","出る",23],["。"]]],"tr":{"az":"Bazar günü üç dost məktəbə çatanda həyətdə böyük bir ağac gördülər. Qutu həmin ağacın altında idi. Onlar torpağı kənara çəkib nəhayət qutunu tapdılar. Qutunu açanda içindən köhnə məktublar və bir fotoşəkil çıxdı.","en":"On Sunday, when the three arrived at school, there was a big tree in the yard. The box was beneath that tree. They removed the soil and finally found the box. When they opened it, they found their old letters and a photograph.","ru":"В воскресенье, когда трое друзей пришли в школу, во дворе уже стояло большое дерево. Коробка была под этим деревом. Они убрали землю и наконец нашли её. Когда открыли коробку, внутри оказались старые письма и фотография."}},{"t":[[["ハル","ハル"],["が","が"],["手紙","てがみ"],["を","を"],["読んだら","よんだら","読む"],["、"],["少し","すこし"],["悲しく","かなしく","悲しい"],["なりました","なりました","なる",2],["。"],["「"],["まだ","まだ"],["夢","ゆめ"],["が","が"],["できていません","できていません","できる",62],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["する","する","する",5],["と","と"],["、"],["ミオ","ミオ"],["は","は"],["「"],["夢","ゆめ"],["が","が"],["まだ","まだ"],["できなくても","できなくても","できる",37],["、"],["大丈夫","だいじょうぶ"],["です","です"],["」"],["と","と"],["笑いました","わらいました","笑う",2],["。"],["ソラ","ソラ"],["も","も"],["「"],["僕","ぼく"],["が","が"],["手伝ったら","てつだったら","手伝う",44],["、"],["きっと","きっと"],["できます","できます","できる",11],["よ","よ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["三人","さんにん"],["は","は"],["もう","もう"],["一度","いちど"],["がんばる","がんばる","がんばる",5],["こと","こと"],["に","に"],["しました","しました","する",2],["。"]]],"tr":{"az":"Haru məktubunu oxuyanda bir az kədərləndi. «Hələ arzumu həyata keçirməmişəm», dedi. Mio gülümsəyərək «Arzun hələ gerçəkləşməsə də, eybi yoxdur», söylədi. Sora da «Mən kömək etsəm, mütləq bacararsan», dedi. Üç dost yenidən çalışmağa qərar verdi.","en":"When Haru read his letter, he felt a little sad. “I still haven't achieved my dream,” he said. Mio smiled and said, “Even if your dream hasn't come true yet, that's all right.” Sora added, “If I help you, I'm sure you can do it.” The three decided to try again.","ru":"Когда Хару прочитал своё письмо, ему стало немного грустно. «Я до сих пор не осуществил свою мечту», сказал он. Мио улыбнулась: «Даже если твоя мечта ещё не сбылась, ничего страшного». Сора добавил: «Если я тебе помогу, у тебя обязательно получится». Трое друзей решили попробовать ещё раз."}},{"t":[[["その","その"],["とき","とき"],["、"],["写真","しゃしん"],["の","の"],["後ろ","うしろ"],["に","に"],["小さな","ちいさな"],["手紙","てがみ"],["が","が"],["ありました","ありました","ある",2],["。"],["先生","せんせい"],["が","が"],["書いた","かいた","書く",0],["手紙","てがみ"],["でした","でした","です",9],["。"],["「"],["十年後","じゅうねんご"],["、"],["みんな","みんな"],["が","が"],["元気","げんき"],["で","で"],["会えたら","あえたら","会えたら",44],["、"],["それ","それ"],["が","が"],["一番","いちばん"],["の","の"],["宝物","たからもの"],["です","です"],["」"],["と","と"],["ありました","ありました","ある",2],["。"],["三人","さんにん"],["は","は"],["その","その"],["意味","いみ"],["を","を"],["考えました","かんがえました","考える",2],["。"],["そして","そして"],["、"],["みんな","みんな"],["で","で"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Elə bu vaxt fotoşəklin arxasında balaca bir məktub gördülər. Məktubu müəllimləri yazmışdı. Orada belə yazılmışdı: «On ildən sonra hamınız sağ-salamat görüşə bilsəniz, ən böyük xəzinə elə budur». Üç dost bu sözlərin mənası barədə düşündü. Sonra hamısı birlikdə güldü.","en":"Just then, they noticed a small letter behind the photograph. It was a letter from their teacher. It said, “If all of you can meet again in good health after ten years, that will be the greatest treasure.” The three thought about what those words meant. Then they all laughed together.","ru":"В этот момент они заметили маленькое письмо за фотографией. Его написал их учитель. Там было сказано: «Если через десять лет вы все сможете встретиться живыми и здоровыми, это и будет самым большим сокровищем». Друзья задумались над смыслом этих слов. А потом все вместе рассмеялись."}},{"t":[[["帰る","かえる","帰る",5],["前","まえ"],["に","に"],["、"],["三人","さんにん"],["は","は"],["新しい","あたらしい"],["箱","はこ"],["を","を"],["用意","ようい"],["しました","しました","する",2],["。"],["今度","こんど"],["は","は"],["十年後","じゅうねんご"],["の","の"],["自分","じぶん"],["に","に"],["小さな","ちいさな"],["手紙","てがみ"],["を","を"],["書きました","かきました","書く",2],["。"],["ハル","ハル"],["は","は"],["「"],["ロボット","ロボット"],["が","が"],["飛ばなくても","とばなくても","飛ぶ",37],["、"],["友達","ともだち"],["と","と"],["空","そら"],["を","を"],["見ます","みます","見る",11],["」"],["と","と"],["書きました","かきました","書く",2],["。"],["する","する","する",5],["と","と"],["、"],["ミオ","ミオ"],["が","が"],["作った","つくった","作る",0],["紙","かみ"],["の","の"],["ロボット","ロボット"],["が","が"],["風","かぜ"],["で","で"],["空","そら"],["へ","へ"],["飛びました","とびました","飛ぶ",2],["。"],["三人","さんにん"],["は","は"],["びっくり","びっくり"],["して","して","する",3],["、"],["また","また"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Getməzdən əvvəl üç dost yeni bir qutu hazırladı. Bu dəfə yenə on il sonrakı özlərinə qısa məktublar yazdılar. Haru yazdı: «Robotum uçmasa da, dostlarımla birlikdə göyə baxacağam». Elə bu vaxt Mionun kağızdan düzəltdiyi robot küləklə havaya qalxdı. Üç dost təəccüblənib yenə güldü.","en":"Before leaving, the three prepared a new box. This time, they wrote short letters to themselves ten years in the future. Haru wrote, “Even if my robot doesn't fly, I'll look at the sky with my friends.” Just then, a paper robot Mio had made flew into the air on the wind. The three were surprised and laughed again.","ru":"Перед уходом трое друзей приготовили новую коробку. На этот раз они написали короткие письма себе ещё через десять лет. Хару написал: «Даже если мой робот не полетит, я буду смотреть на небо вместе с друзьями». И вдруг бумажный робот, которого сделала Мио, взлетел в воздух от порыва ветра. Все трое удивились и снова рассмеялись."}}]},{"id":"l25c","ti":[[["おばあさん","おばあさん"],["の","の"],["最後","さいご"],["の","の"],["配達","はいたつ"]]],"tt":{"az":"Nənənin son çatdırılması","en":"Grandma's Last Delivery","ru":"Последняя доставка бабушки"},"P":[{"t":[[["小さな","ちいさな"],["町","まち"],["に","に"],["、"],["花屋","はなや"],["で","で"],["働く","はたらく","働く",5],["ユキ","ユキ"],["と","と"],["いう","いう","いう",5],["女の子","おんなのこ"],["が","が"],["いました","いました","いる",2],["。"],["ユキ","ユキ"],["は","は"],["毎朝","まいあさ"],["、"],["花","はな"],["を","を"],["自転車","じてんしゃ"],["で","で"],["届けました","とどけました","届ける",2],["。"],["ある日","あるひ"],["、"],["店","みせ"],["に","に"],["一人","ひとり"],["の","の"],["おばあさん","おばあさん"],["が","が"],["来ました","きました","来る",2],["。"],["おばあさん","おばあさん"],["は","は"],["赤い","あかい"],["花","はな"],["を","を"],["一本","いっぽん"],["買って","かって","買う",3],["、"],["「"],["明日","あした"],["の","の"],["朝","あさ"],["、"],["駅","えき"],["へ","へ"],["届けてください","とどけてください","届ける",35],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"]]],"tr":{"az":"Kiçik bir şəhərdə gül mağazasında işləyən Yuki adlı bir qız yaşayırdı. Yuki hər səhər gülləri velosipedlə çatdırırdı. Bir gün mağazaya yaşlı bir qadın gəldi. Qadın bir qırmızı gül alıb «Sabah səhər bunu vağzala çatdırın», deyə xahiş etdi.","en":"In a small town, there was a girl named Yuki who worked at a flower shop. Every morning, Yuki delivered flowers by bicycle. One day, an elderly woman came into the shop. She bought one red flower and asked, “Please deliver this to the station tomorrow morning.”","ru":"В маленьком городе жила девушка по имени Юки, которая работала в цветочном магазине. Каждое утро Юки развозила цветы на велосипеде. Однажды в магазин пришла пожилая женщина. Она купила один красный цветок и попросила: «Пожалуйста, доставьте его завтра утром на станцию»."}},{"t":[[["ユキ","ユキ"],["は","は"],["「"],["誰","だれ"],["に","に"],["渡します","わたします","渡す",11],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["朝","あさ"],["九","きゅう"],["時","じ"],["に","に"],["来る","くる","来る",5],["人","ひと"],["です","です"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"],["名前","なまえ"],["も","も"],["電話","でんわ"],["番号","ばんごう"],["も","も"],["ありませんでした","ありませんでした","ある",4],["。"],["ユキ","ユキ"],["は","は"],["少し","すこし"],["困りました","こまりました","困る",2],["が","が"],["、"],["手紙","てがみ"],["も","も"],["いっしょ","いっしょ"],["に","に"],["預かりました","あずかりました","預かりました",2],["。"]]],"tr":{"az":"Yuki «Kimə verməliyəm?» deyə soruşdu. Yaşlı qadın «Səhər saat doqquzda gələcək adama», deyə cavab verdi. Nə ad vardı, nə də telefon nömrəsi. Yuki bir az çaşqın qaldı, amma güllə birlikdə məktubu da götürdü.","en":"Yuki asked, “Who should I give it to?” The woman answered, “To the person who comes at nine in the morning.” There was no name or phone number. Yuki was a little troubled, but she accepted a letter along with the flower.","ru":"Юки спросила: «Кому его передать?» Женщина ответила: «Человеку, который придёт в девять утра». Ни имени, ни номера телефона не было. Юки немного растерялась, но взяла вместе с цветком и письмо."}},{"t":[[["次","つぎ"],["の","の"],["朝","あさ"],["、"],["ユキ","ユキ"],["が","が"],["家","いえ"],["を","を"],["出たら","でたら","出る",44],["、"],["強い","つよい"],["雨","あめ"],["が","が"],["降っていました","ふっていました","降る",15],["。"],["雨","あめ"],["が","が"],["降っても","ふっても","降る",34],["、"],["ユキ","ユキ"],["は","は"],["自転車","じてんしゃ"],["で","で"],["駅","えき"],["へ","へ"],["行きました","いきました","行く",2],["。"],["でも","でも"],["、"],["駅","えき"],["に","に"],["着いたら","ついたら","着いたら",44],["、"],["もう","もう"],["九","きゅう"],["時","じ"],["十","じゅう"],["分","ふん"],["でした","でした","です",9],["。"],["電車","でんしゃ"],["は","は"],["出た","でた","出る",0],["後","あと"],["でした","でした","です",9],["。"],["ユキ","ユキ"],["は","は"],["「"],["もし","もし"],["早く","はやく","早い"],["来たら","きたら","来る",44],["、"],["会えた","あえた","会えた",0],["の","の"],["に","に"],["」"],["と","と"],["考えました","かんがえました","考える",2],["。"]]],"tr":{"az":"Ertəsi səhər Yuki evdən çıxanda güclü yağış yağırdı. Yağışa baxmayaraq, velosipedlə vağzala getdi. Amma çatanda saat artıq doqquzu on dəqiqə keçmişdi. Qatar yola düşmüşdü. Yuki «Kaş daha tez gəlsəydim, bəlkə onunla görüşərdim», deyə düşündü.","en":"The next morning, when Yuki left home, it was raining heavily. Even though it was raining, she rode her bicycle to the station. But when she arrived, it was already ten past nine. The train had already left. Yuki thought, “If only I'd come earlier, I could have met that person.”","ru":"На следующее утро, когда Юки вышла из дома, шёл сильный дождь. Несмотря на дождь, она поехала на станцию на велосипеде. Но когда приехала, было уже десять минут десятого. Поезд уже ушёл. Юки подумала: «Если бы я приехала раньше, то смогла бы встретить этого человека»."}},{"t":[[["ユキ","ユキ"],["は","は"],["駅","えき"],["で","で"],["花","はな"],["を","を"],["持って","もって","持つ",3],["待ちました","まちました","待つ",2],["。"],["暇な","ひまな","暇",1],["時間","じかん"],["が","が"],["あっても","あっても","ある",34],["、"],["帰りませんでした","かえりませんでした","帰る",4],["。"],["する","する","する",5],["と","と"],["、"],["小さな","ちいさな"],["男の子","おとこのこ"],["が","が"],["来ました","きました","来る",2],["。"],["男の子","おとこのこ"],["は","は"],["「"],["その","その"],["花","はな"],["は","は"],["誰","だれ"],["の","の"],["です","です"],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["ユキ","ユキ"],["が","が"],["説明","せつめい"],["したら","したら","する",44],["、"],["男の子","おとこのこ"],["は","は"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Yuki vağzalda əlində güllə gözlədi. Boş vaxtı olsa da, geri qayıtmadı. Bir az sonra balaca bir oğlan gəldi. Oğlan «Bu gül kimindir?» deyə soruşdu. Yuki vəziyyəti izah edəndə oğlan gülümsədi.","en":"Yuki waited at the station with the flower in her hand. Even though she had time to spare, she did not go home. Then a little boy came over. “Whose flower is that?” he asked. When Yuki explained, the boy smiled.","ru":"Юки ждала на станции с цветком в руках. Хотя у неё было свободное время, она не уходила домой. Вскоре подошёл маленький мальчик. «Чей это цветок?» спросил он. Когда Юки объяснила ситуацию, мальчик улыбнулся."}},{"t":[[["男の子","おとこのこ"],["は","は"],["「"],["僕","ぼく"],["の","の"],["おじいさん","おじいさん"],["は","は"],["今日","きょう"],["、"],["遠く","とおく"],["の","の"],["町","まち"],["へ","へ"],["行きます","いきます","行く",11],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["「"],["おばあさん","おばあさん"],["は","は"],["昨日","きのう"],["、"],["『"],["もし","もし"],["会えなくても","あえなくても","会えなくても",37],["、"],["花","はな"],["を","を"],["届けたい","とどけたい","届ける",30],["』"],["と","と"],["言っていました","いっていました","言う",15],["」"],["と","と"],["話しました","はなしました","話す",2],["。"],["ユキ","ユキ"],["は","は"],["男の子","おとこのこ"],["に","に"],["手紙","てがみ"],["を","を"],["見せました","みせました","見せる",2],["。"],["男の子","おとこのこ"],["は","は"],["「"],["これ","これ"],["は","は"],["おじいさん","おじいさん"],["へ","へ"],["の","の"],["手紙","てがみ"],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Oğlan dedi: «Mənim babam bu gün uzaq bir şəhərə gedir». Sonra əlavə etdi: «Nənəm dünən demişdi ki, görüşə bilməsə də, ona gül göndərmək istəyir». Yuki məktubu oğlana göstərdi. Oğlan «Bu məktub babam üçündür», dedi.","en":"The boy said, “My grandfather is going to a distant town today.” Then he added, “Yesterday, Grandma said she wanted to send him a flower even if she couldn't see him.” Yuki showed the boy the letter. “This letter is for Grandpa,” he said.","ru":"Мальчик сказал: «Мой дедушка сегодня уезжает в далёкий город». Потом добавил: «Вчера бабушка говорила, что хочет передать ему цветок, даже если не сможет встретиться с ним». Юки показала мальчику письмо. «Это письмо для дедушки», сказал он."}},{"t":[[["ユキ","ユキ"],["は","は"],["男の子","おとこのこ"],["と","と"],["いっしょ","いっしょ"],["に","に"],["次","つぎ"],["の","の"],["駅","えき"],["へ","へ"],["行きました","いきました","行く",2],["。"],["お金","おかね"],["が","が"],["あまり","あまり"],["なくても","なくても","ない",34],["、"],["二人","ふたり"],["は","は"],["電車","でんしゃ"],["に","に"],["乗りました","のりました","乗る",2],["。"],["次","つぎ"],["の","の"],["駅","えき"],["に","に"],["着いたら","ついたら","着いたら",44],["、"],["白い","しろい"],["髪","かみ"],["の","の"],["おじいさん","おじいさん"],["が","が"],["いました","いました","いる",2],["。"],["おじいさん","おじいさん"],["は","は"],["道","みち"],["で","で"],["小さな","ちいさな"],["犬","いぬ"],["を","を"],["助けて","たすけて","助ける",3],["、"],["電車","でんしゃ"],["に","に"],["遅れた","おくれた","遅れた",0],["の","の"],["です","です"],["。"]]],"tr":{"az":"Yuki oğlanla birlikdə növbəti stansiyaya getdi. Pulları çox olmasa da, qatara mindilər. Növbəti stansiyaya çatanda ağ saçlı bir qoca gördülər. Məlum oldu ki, qoca yolda balaca bir itə kömək etdiyi üçün qatarına gecikmişdi.","en":"Yuki went to the next station with the boy. Even though they did not have much money, they took the train. When they arrived, they saw an old man with white hair. He had missed his train because he had stopped to help a little dog on the road.","ru":"Юки вместе с мальчиком отправилась на следующую станцию. Хотя денег у них было немного, они сели на поезд. Когда приехали, то увидели седого старика. Оказалось, он опоздал на поезд, потому что по дороге помог маленькой собаке."}},{"t":[[["おじいさん","おじいさん"],["が","が"],["花","はな"],["と","と"],["手紙","てがみ"],["を","を"],["受け取ったら","うけとったら","受け取ったら",44],["、"],["目","め"],["に","に"],["涙","なみだ"],["が","が"],["出ました","でました","出る",2],["。"],["手紙","てがみ"],["に","に"],["は","は"],["「"],["転勤","てんきん"],["で","で"],["遠く","とおく"],["へ","へ"],["行っても","いっても","行く",34],["、"],["毎日","まいにち"],["元気","げんき"],["で","で"],["いてください","いてください","いる",35],["。"],["五十年間","ごじゅうねんかん"],["、"],["ありがとう","ありがとう"],["」"],["と","と"],["書いてありました","かいてありました","書く",36],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["実","じつ"],["は","は"],["、"],["今日","きょう"],["は","は"],["結婚","けっこん"],["五十年","ごじゅうねん"],["の","の"],["日","ひ"],["です","です"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ユキ","ユキ"],["は","は"],["びっくり","びっくり"],["しました","しました","する",2],["。"]]],"tr":{"az":"Qoca gülü və məktubu alanda gözləri doldu. Məktubda yazılmışdı: «İşinə görə uzağa köçsən də, hər gün sağlam ol. Əlli il üçün təşəkkür edirəm». Qoca «Əslində, bu gün evliliyimizin əlli illiyidir», dedi. Yuki çox təəccübləndi.","en":"When the old man received the flower and letter, tears filled his eyes. The letter said, “Even though your job transfer is taking you far away, please stay healthy every day. Thank you for fifty years.” The old man said, “Actually, today is our fiftieth wedding anniversary.” Yuki was astonished.","ru":"Когда старик получил цветок и письмо, на его глазах выступили слёзы. В письме было написано: «Даже если из-за перевода по работе ты уедешь далеко, береги себя каждый день. Спасибо за пятьдесят лет». Старик сказал: «Вообще-то сегодня пятидесятая годовщина нашей свадьбы». Юки очень удивилась."}},{"t":[[["その","その"],["夕方","ゆうがた"],["、"],["ユキ","ユキ"],["が","が"],["店","みせ"],["に","に"],["戻ったら","もどったら","戻る",44],["、"],["おばあさん","おばあさん"],["が","が"],["待っていました","まっていました","待つ",15],["。"],["おばあさん","おばあさん"],["は","は"],["「"],["花","はな"],["が","が"],["届いたら","とどいたら","届く",44],["、"],["主人","しゅじん"],["は","は"],["きっと","きっと"],["笑う","わらう","笑う",5],["と","と"],["思いました","おもいました","思う",2],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ユキ","ユキ"],["は","は"],["「"],["おじいさん","おじいさん"],["も","も"],["、"],["犬","いぬ"],["も","も"],["元気","げんき"],["でした","でした","です",9],["よ","よ"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"],["する","する","する",5],["と","と"],["、"],["おばあさん","おばあさん"],["は","は"],["笑って","わらって","笑う",3],["、"],["「"],["あの","あの"],["人","ひと"],["は","は"],["昔","むかし"],["から","から"],["、"],["犬","いぬ"],["を","を"],["見たら","みたら","見る",44],["電車","でんしゃ"],["に","に"],["遅れる","おくれる","遅れる",5],["ん","ん"],["です","です"],["よ","よ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ユキ","ユキ"],["も","も"],["大きな","おおきな"],["声","こえ"],["で","で"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Həmin axşam Yuki mağazaya qayıdanda yaşlı qadın onu gözləyirdi. Qadın dedi: «Gül ona çatsa, mütləq gülümsəyəcəyini düşünürdüm». Yuki «Babanın da, itin də vəziyyəti yaxşı idi», deyə cavab verdi. Qadın gülərək «O, lap cavanlığından belədir, bir it görən kimi qatarına gecikir», dedi. Yuki də ürəkdən güldü.","en":"That evening, when Yuki returned to the shop, the elderly woman was waiting. She said, “I thought my husband would surely smile if the flower reached him.” Yuki replied, “Both your husband and the dog were doing fine.” The woman laughed and said, “He's been like that since he was young. Whenever he sees a dog, he misses his train!” Yuki burst out laughing too.","ru":"В тот вечер, когда Юки вернулась в магазин, пожилая женщина ждала её. Она сказала: «Я думала, что муж обязательно улыбнётся, если получит цветок». Юки ответила: «И с вашим мужем, и с собакой всё было хорошо». Женщина рассмеялась: «Он такой с молодости. Стоит ему увидеть собаку, как он опаздывает на поезд!» Юки тоже громко рассмеялась."}}]}],"G":{"あげる":{"b":"あげる","p":"v","m":{"az":"vermək, hədiyyə etmək","en":"give","ru":"давать, дарить"},"n":{"az":"Alan şəxs に, verilən şey を ilə işlənir: 友達に本をあげる; danışana verilən şey üçün adətən くれる işlənir.","en":"The recipient takes に and the gift を, as in 友達に本をあげる; giving to the speaker is usually expressed with くれる.","ru":"Получатель обозначается с に, подарок с を: 友達に本をあげる; когда дают говорящему, обычно используется くれる."}},"あの":{"b":"あの","p":"dm","m":{"az":"o (uzaqdakı)","en":"that (over there)","ru":"тот (вдали)"},"n":{"az":"İsimdən əvvəl gəlir: あの人 = o adam, あの星 = o ulduz. Danışandan da, dinləyəndən də uzaq olan şey.","en":"Comes before a noun: あの人 = that person, あの星 = that star. Something far from both speakers.","ru":"Ставится перед существительным: あの人 = тот человек. Далеко от обоих собеседников."}},"あまり":{"b":"あまり","p":"ad","m":{"az":"o qədər də, çox da","en":"not very, not much","ru":"не очень, не особо"},"n":{"az":"Adətən inkarla işlənir: あまり寒くない = o qədər də soyuq deyil.","en":"Usually used with a negative: あまり寒くない = not very cold.","ru":"Обычно используется с отрицанием: あまり寒くない = не очень холодно."}},"ありがとう":{"b":"ありがとう","p":"ex","m":{"az":"sağ ol","en":"thank you","ru":"спасибо"},"n":{"az":"Daha nəzakətli: ありがとうございます.","en":"More polite: ありがとうございます.","ru":"Вежливее: ありがとうございます."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いっしょ":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlikdə","en":"together","ru":"вместе"},"n":{"az":"いっしょに = birlikdə.","en":"いっしょに = together.","ru":"いっしょに = вместе."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"おじいさん":{"b":"おじいさん","p":"n","m":{"az":"baba; qoca kişi","en":"grandfather; old man","ru":"дедушка; старик"}},"おなか":{"b":"おなか","p":"n","m":{"az":"qarın","en":"stomach, belly","ru":"живот"},"n":{"az":"おなかがすく “acmaq”, おなかがいっぱい isə “tox olmaq” deməkdir.","en":"おなかがすく means “get hungry,” and おなかがいっぱい means “be full.”","ru":"おなかがすく означает «проголодаться», а おなかがいっぱい означает «быть сытым»."}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"お金":{"b":"お金 (おかね)","p":"n","m":{"az":"pul","en":"money","ru":"деньги"}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"これ":{"b":"これ","p":"pr","m":{"az":"bu; bu şey","en":"this; this thing","ru":"это; эта вещь"},"n":{"az":"Danışana yaxın şeyi bildirir və isimdən əvvəl işlənmir; isimdən əvvəl この gəlir.","en":"Refers to something near the speaker; use この before a noun.","ru":"Указывает на предмет рядом с говорящим; перед существительным используется この."}},"すく":{"b":"すく (空く)","p":"v","m":{"az":"acmaq, boşalmaq","en":"to become empty, to get hungry","ru":"опустеть, проголодаться"},"n":{"az":"I qrup feldir: おなかがすきました = acdım; 空く həm də boşalmaq deməkdir.","en":"A Group 1 verb: おなかがすきました = I got hungry; 空く can also mean to become empty.","ru":"Глагол I группы: おなかがすきました = я проголодался; 空く также означает опустеть."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それ":{"b":"それ","p":"pr","m":{"az":"o; həmin şey","en":"that; that thing","ru":"то; эта вещь"},"n":{"az":"Dinləyənə yaxın və ya əvvəl qeyd edilmiş şeyi bildirir.","en":"Refers to something near the listener or already mentioned.","ru":"Указывает на предмет рядом со слушающим или на уже упомянутое."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"ない":{"b":"無い (ない)","p":"ai","m":{"az":"yoxdur; mövcud deyil","en":"not exist; not have","ru":"нет; отсутствует"},"n":{"az":"İ-sifət kimi dəyişir: なく və なかった; felə qoşulduqda inkar da bildirir.","en":"Inflects like an i-adjective: なく and なかった; attached to a verb, it also marks negation.","ru":"Изменяется как и-прилагательное: なく и なかった; при глаголе также выражает отрицание."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もらう":{"b":"もらう","p":"v","m":{"az":"almaq, hədiyyə almaq","en":"to receive, to get","ru":"получать"},"n":{"az":"Verən şəxs に və ya から ilə göstərilir: 友達に本をもらう.","en":"The giver takes に or から: 友達に本をもらう, receive a book from a friend.","ru":"Даритель обозначается через に или から: 友達に本をもらう, получить книгу от друга."}},"や":{"b":"や","p":"pt","m":{"az":"və, ... kimi","en":"and, things such as","ru":"и, например"},"n":{"az":"や tam olmayan siyahı yaradır: 犬や猫（など）; nida və çağırışda da işlənir: おや、太郎や.","en":"や gives a non-exhaustive list, 犬や猫（など）, and also appears in exclamations or calls, おや、太郎や.","ru":"や обозначает неполный перечень, 犬や猫（など）, а также встречается в восклицаниях и обращениях: おや、太郎や."}},"やっと":{"b":"やっと","p":"ad","m":{"az":"nəhayət, güclə","en":"finally, barely","ru":"наконец, едва"},"n":{"az":"Uzun gözləmə və ya çətinlikdən sonra nəticəni, bəzən də güclə çatmağı bildirir.","en":"Indicates a result after waiting or effort, or sometimes barely managing something.","ru":"Обозначает результат после ожидания или усилий, иногда достижение чего-либо с трудом."}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"より":{"b":"より","p":"pt","m":{"az":"-dan/-dən daha (müqayisə)","en":"than","ru":"чем"},"n":{"az":"さっきより明るく = bayaqkından daha parlaq.","en":"さっきより明るく = brighter than before.","ru":"さっきより明るく = ярче, чем раньше."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ん":{"b":"ん (← の)","p":"pt","m":{"az":"(izah bildirir)","en":"(explanatory)","ru":"(пояснение)"},"n":{"az":"〜んです / 〜のです: səbəb və ya izah verəndə işlənir; danışıqda の → ん.","en":"〜んです / 〜のです adds an explanation; in speech の becomes ん.","ru":"〜んです / 〜のです – объяснение; в речи の → ん."}},"ソラ":{"b":"ソラ","p":"nm","m":{"az":"Sora","en":"Sora","ru":"Сора"}},"ハル":{"b":"ハル","p":"nm","m":{"az":"Haru","en":"Haru","ru":"Хару"}},"ユキ":{"b":"ユキ","p":"nm","m":{"az":"Yuki (qız adı, 'qar' deməkdir)","en":"Yuki (girl's name, means 'snow')","ru":"Юки (имя, значит 'снег')"}},"ロボット":{"b":"ロボット","p":"n","m":{"az":"robot","en":"robot","ru":"робот"},"n":{"az":"Katakana ilə yazılır, çünki xarici mənşəli sözdür.","en":"Written in katakana because it is a loanword.","ru":"Пишется катаканой, так как это заимствование."}},"一人":{"b":"一人 (ひとり)","p":"n","m":{"az":"tək, bir nəfər","en":"alone; one person","ru":"один (человек)"},"n":{"az":"一人で = təkbaşına.","en":"一人で = alone.","ru":"一人で = в одиночку."}},"一度":{"b":"一度 (いちど)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"}},"一本":{"b":"一本 (いっぽん)","p":"n","m":{"az":"bir dənə (uzun əşya)","en":"one (long thing)","ru":"одна штука (длинная)"},"n":{"az":"本 – uzun, nazik əşyalar üçün sayğac (bambuk, qələm, şüşə).","en":"本 – counter for long, thin things.","ru":"本 – счётный суффикс для длинных предметов."}},"一枚":{"b":"一枚 (いちまい)","p":"nu","m":{"az":"bir ədəd yastı əşya","en":"one flat object","ru":"один плоский предмет"},"n":{"az":"枚 kağız, şəkil və köynək kimi nazik, yastı əşyaları saymaq üçün işlənir.","en":"枚 counts thin, flat objects such as sheets of paper, pictures, and shirts.","ru":"枚 используется для счёта тонких плоских предметов, например листов бумаги, картинок и рубашек."}},"一番":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən; hamıdan çox","en":"most; best","ru":"самый; больше всего"},"n":{"az":"Sifətdən əvvəl üstünlük bildirir: 一番大きい = ən böyük; isim kimi «birinci yer» deməkdir.","en":"Before an adjective it marks the superlative: 一番大きい = biggest; as a noun it means first place.","ru":"Перед прилагательным выражает превосходную степень: 一番大きい = самый большой; как существительное означает первое место."}},"三人":{"b":"三人 (さんにん)","p":"nu","m":{"az":"üç nəfər","en":"three people","ru":"три человека"},"n":{"az":"人 insan sayğacıdır: 一人 hitori, 二人 futari, 三人 sannin.","en":"人 counts people: 一人 hitori, 二人 futari, 三人 sannin.","ru":"人 считает людей: 一人 hitori, 二人 futari, 三人 sannin."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"不思議":{"b":"不思議 (ふしぎ)","p":"an","m":{"az":"sirli; qəribə","en":"mysterious; curious","ru":"загадочный; удивительный"},"n":{"az":"な-sifətidir: 不思議な話; isim kimi «sirr, möcüzə» də bildirir.","en":"A な-adjective: 不思議な話; as a noun it can mean a mystery or wonder.","ru":"な-прилагательное: 不思議な話; как существительное может означать тайну или чудо."}},"乗る":{"b":"乗る (のる)","p":"v","m":{"az":"minmək","en":"board, ride","ru":"садиться в транспорт, ехать"},"n":{"az":"Nəqliyyat vasitəsi に ilə işlənir: 電車に乗る “qatara minmək”.","en":"The vehicle takes に: 電車に乗る means “board a train.”","ru":"Транспорт обозначается с に: 電車に乗る «сесть в поезд»."}},"九":{"b":"九 (きゅう／く)","p":"nu","m":{"az":"doqquz","en":"nine","ru":"девять"},"n":{"az":"Oxunuş birləşmədən asılıdır: 九人 きゅうにん, 九時 くじ, 九月 くがつ.","en":"The reading depends on the combination: 九人 きゅうにん, 九時 くじ, 九月 くがつ.","ru":"Чтение зависит от сочетания: 九人 きゅうにん, 九時 くじ, 九月 くがつ."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"今":{"b":"今 (いま)","p":"n","m":{"az":"indi","en":"now","ru":"сейчас"},"n":{"az":"今も = indi də.","en":"今も = even now.","ru":"今も = и сейчас."}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"仕事":{"b":"仕事 (しごと)","p":"n","m":{"az":"iş","en":"work, job","ru":"работа"}},"会う":{"b":"会う (あう)","p":"v","m":{"az":"görüşmək, rastlaşmaq","en":"meet, see someone","ru":"встречаться, встречать"},"n":{"az":"Görüşülən şəxs に və ya と ilə işlənir: 友達に会う “dostla görüşmək”; て-forması 会って olur.","en":"The person met takes に or と, as in 友達に会う “meet a friend”; the て-form is 会って.","ru":"Человек, с которым встречаются, обозначается с に или と: 友達に会う «встретиться с другом»; форма на て: 会って."}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"働く":{"b":"働く (はたらく)","p":"v","m":{"az":"işləmək","en":"to work","ru":"работать"},"n":{"az":"İş yerini で göstərir: 銀行で働きます.","en":"The workplace takes で: 銀行で働きます.","ru":"Место работы обозначается через で: 銀行で働きます."}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"写真":{"b":"写真 (しゃしん)","p":"n","m":{"az":"fotoşəkil","en":"photograph","ru":"фотография"}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"分":{"b":"分 (ふん／ぷん)","p":"nu","m":{"az":"dəqiqə","en":"minute","ru":"минута"},"n":{"az":"Dəqiqə sayğacıdır: 一分 ippun, 六分 roppun, 八分 happun, 十分 juppun.","en":"Minute counter: 一分 ippun, 六分 roppun, 八分 happun, 十分 juppun.","ru":"Счётное слово для минут: 一分 ippun, 六分 roppun, 八分 happun, 十分 juppun."}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"助ける":{"b":"助ける (たすける)","p":"v","m":{"az":"kömək etmək; xilas etmək","en":"help; rescue","ru":"помогать; спасать"},"n":{"az":"Təsirli feldir və kömək edilən şəxs を ilə göstərilir; 助かる xilas olmaq deməkdir.","en":"A transitive verb with the person helped marked by を; 助かる means to be saved.","ru":"Переходный глагол: человек, которому помогают, оформляется を; 助かる означает спастись."}},"勉強":{"b":"勉強 (べんきょう)","p":"n","m":{"az":"dərs oxuma; təhsil","en":"study; learning","ru":"учёба; обучение"},"n":{"az":"勉強する = dərs oxumaq, öyrənmək.","en":"勉強する means to study.","ru":"勉強する означает учиться, изучать."}},"十":{"b":"十 (じゅう)","p":"nu","m":{"az":"on","en":"ten","ru":"десять"}},"友達":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг"}},"取る":{"b":"取る (とる)","p":"v","m":{"az":"götürmək, almaq","en":"to take, to pick up","ru":"брать, поднимать"},"n":{"az":"Əşyanı götürmək üçün 取る, şəkil çəkmək üçün eyni oxunuşlu 撮る işlənir.","en":"Use 取る for taking an object and the identically pronounced 撮る for taking a photo.","ru":"Для взятия предмета используется 取る, а для фотографии используется 撮る с тем же чтением."}},"右":{"b":"右 (みぎ)","p":"n","m":{"az":"sağ, sağ tərəf","en":"right, right side","ru":"право, правая сторона"},"n":{"az":"右に = sağa; 右の手 = sağ əl.","en":"右に = to the right; 右の手 = right hand.","ru":"右に = направо; 右の手 = правая рука."}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"喜ぶ":{"b":"喜ぶ (よろこぶ)","p":"v","m":{"az":"sevinmək, şadlanmaq","en":"to rejoice, to be pleased","ru":"радоваться, обрадоваться"},"n":{"az":"I qrup feldir: 喜びました = sevindi; プレゼントを喜ぶ = hədiyyəyə sevinmək.","en":"A Group 1 verb: 喜びました = was pleased; プレゼントを喜ぶ = to be delighted with a gift.","ru":"Глагол I группы: 喜びました = обрадовался; プレゼントを喜ぶ = радоваться подарку."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"土":{"b":"土 (つち)","p":"n","m":{"az":"torpaq","en":"soil, earth","ru":"земля, почва"}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"外国":{"b":"外国 (がいこく)","p":"n","m":{"az":"xarici ölkə","en":"foreign country","ru":"зарубежная страна"}},"多い":{"b":"多い (おおい)","p":"ai","m":{"az":"çox; çoxsaylı","en":"many; numerous","ru":"многочисленный; много"},"n":{"az":"い-sifətdir; 多くて bağlayıcı formadır və adətən 人が多い deyilir.","en":"It is an i-adjective; 多くて is its linking form, and 人が多い is the usual pattern.","ru":"Это i-прилагательное; 多くて - соединительная форма, обычно говорят 人が多い."}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"夢":{"b":"夢 (ゆめ)","p":"n","m":{"az":"yuxu, arzu","en":"dream","ru":"сон, мечта"}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大丈夫":{"b":"大丈夫 (だいじょうぶ)","p":"an","m":{"az":"yaxşı, təhlükəsiz, problem yoxdur","en":"all right, okay, safe","ru":"в порядке, всё хорошо, безопасно"},"n":{"az":"な sifətidir, 大丈夫です problem yoxdur deməkdir.","en":"A na-adjective, with 大丈夫です meaning it is okay.","ru":"Прилагательное на な, 大丈夫です означает всё в порядке."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"実":{"b":"実 (み)","p":"n","m":{"az":"meyvə, bar, toxum","en":"fruit, berry, seed","ru":"плод, ягода, семя"},"n":{"az":"実がなる - ağacın və ya bitkinin bar verməsi.","en":"実がなる means for a tree or plant to bear fruit.","ru":"実がなる означает плодоносить."}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"届く":{"b":"届く (とどく)","p":"v","m":{"az":"çatmaq, gəlib çatmaq","en":"to arrive, to reach","ru":"доходить, прибывать"},"n":{"az":"荷物が届く bağlamanın çatmasını, 荷物を届ける isə bağlamanı çatdırmağı bildirir.","en":"荷物が届く means a parcel arrives; 荷物を届ける means to deliver a parcel.","ru":"荷物が届く означает, что посылка пришла, а 荷物を届ける значит доставить посылку."}},"届ける":{"b":"届ける (とどける)","p":"v","m":{"az":"çatdırmaq, təhvil vermək","en":"to deliver, to hand over","ru":"доставлять, передавать"},"n":{"az":"Təsirli feldir, 荷物を届けます bağlamanı çatdırmaqdır, 届く isə gəlib çatmaqdır.","en":"Transitive: 荷物を届けます means deliver a package, while 届く means to arrive.","ru":"Переходный глагол: 荷物を届けます - доставить посылку, а 届く означает прибыть."}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"島":{"b":"島 (しま)","p":"n","m":{"az":"ada","en":"island","ru":"остров"}},"左":{"b":"左 (ひだり)","p":"n","m":{"az":"sol, sol tərəf","en":"left, left side","ru":"лево, левая сторона"},"n":{"az":"左に = sola; 左の手 = sol əl.","en":"左に = to the left; 左の手 = left hand.","ru":"左に = налево; 左の手 = левая рука."}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"店":{"b":"店 (みせ)","p":"n","m":{"az":"mağaza; dükan","en":"shop; store","ru":"магазин; лавка"}},"庭":{"b":"庭 (にわ)","p":"n","m":{"az":"bağça, həyət","en":"garden, yard","ru":"сад, двор"}},"弟":{"b":"弟 (おとうと)","p":"n","m":{"az":"kiçik qardaş","en":"younger brother","ru":"младший брат"},"n":{"az":"Adətən öz kiçik qardaşından danışarkən işlənir.","en":"Usually used when speaking about one's own younger brother.","ru":"Обычно используется при упоминании своего младшего брата."}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"待つ":{"b":"待つ (まつ)","p":"v","m":{"az":"gözləmək","en":"wait for","ru":"ждать"},"n":{"az":"Gözlənilən şəxs və ya şey を ilə işlənir; て-forması 待って olur.","en":"The person or thing awaited takes を; the て-form is 待って.","ru":"Тот, кого ждут, или то, чего ждут, обозначается с を; форма на て: 待って."}},"後":{"b":"後 (あと)","p":"n","m":{"az":"sonra; arxası","en":"after; behind","ru":"после; позади"},"n":{"az":"時間の後 = vaxtdan sonra; 後で = sonra; bəzi birləşmələrdə ご oxunur.","en":"時間の後 means after a time; 後で means later; some compounds use the reading ご.","ru":"時間の後 означает «после указанного времени», 後で = потом; в некоторых сочетаниях читается ご."}},"後ろ":{"b":"後ろ (うしろ)","p":"n","m":{"az":"arxa, arxa tərəf","en":"back, behind","ru":"задняя сторона, позади"},"n":{"az":"Nの後ろ bir şeyin arxasını bildirir: 家の後ろ evin arxası.","en":"Nの後ろ means behind something: 家の後ろ, behind the house.","ru":"Nの後ろ означает «позади чего-либо»: 家の後ろ, за домом."}},"忘れる":{"b":"忘れる (わすれる)","p":"v","m":{"az":"unutmaq","en":"to forget","ru":"забывать"},"n":{"az":"Nを忘れる həm nəyisə unutmaq, həm də bir yerdə qoyub gəlmək mənasında işlənir.","en":"Nを忘れる can mean to forget something or leave it behind.","ru":"Nを忘れる может означать забыть что-либо или оставить это где-либо."}},"忙しい":{"b":"忙しい (いそがしい)","p":"ai","m":{"az":"məşğul","en":"busy","ru":"занятой"},"n":{"az":"İ-sifətdir; 忙しく onun zərf formasıdır.","en":"An i-adjective; 忙しく is its adverbial form.","ru":"И-прилагательное; 忙しく является его наречной формой."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"悲しい":{"b":"悲しい (かなしい)","p":"ai","m":{"az":"kədərli","en":"sad","ru":"грустный"},"n":{"az":"İ-sifətidir; 悲しく zərf formasıdır və “kədərli şəkildə” mənasını verir.","en":"An i-adjective; 悲しく is its adverbial form, meaning “sadly.”","ru":"Прилагательное на い; 悲しく является наречной формой со значением «грустно»."}},"戻る":{"b":"戻る (もどる)","p":"v","m":{"az":"qayıtmaq; geri dönmək","en":"return; go back","ru":"возвращаться"},"n":{"az":"Təsirsiz feldir; 戻す nəyisə geri qaytarmaq deməkdir.","en":"An intransitive verb; 戻す means to put or bring something back.","ru":"Непереходный глагол; 戻す означает вернуть что-либо."}},"手伝う":{"b":"手伝う (てつだう)","p":"v","m":{"az":"kömək etmək","en":"to help; to assist","ru":"помогать"},"n":{"az":"手伝いましょう təklif bildirir: kömək edim.","en":"手伝いましょう offers help: shall I help?","ru":"手伝いましょう выражает предложение помощи: давайте помогу."}},"手紙":{"b":"手紙 (てがみ)","p":"n","m":{"az":"məktub","en":"letter","ru":"письмо"}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"日曜":{"b":"日曜 (にちよう)","p":"n","m":{"az":"bazar günü","en":"Sunday","ru":"воскресенье"}},"早い":{"b":"早い (はやい)","p":"ai","m":{"az":"erkən; tez","en":"early","ru":"ранний; рано"},"n":{"az":"い-sifətidir; 早く zərf formasıdır, sürət mənasında isə 速い yazılır.","en":"An い-adjective; 早く is its adverb form, while 速い refers to speed.","ru":"い-прилагательное; 早く является наречной формой, а 速い обозначает скорость."}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"昔":{"b":"昔 (むかし)","p":"n","m":{"az":"keçmiş, qədim zamanlar","en":"the past, long ago","ru":"прошлое, давние времена"}},"昨日":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 昨日来ました.","en":"Usually takes no に as a time expression: 昨日来ました.","ru":"При обозначении времени обычно употребляется без に: 昨日来ました."}},"時":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, zaman","en":"time, occasion","ru":"время, момент"},"n":{"az":"時 “vaxt” mənasında とき, saat bildirən rəqəmdən sonra isə じ oxunur: 三時 “saat üç”.","en":"時 is read とき for “time” but じ after a number indicating the hour: 三時 “three o'clock.”","ru":"時 читается とき в значении «время», но じ после числа, обозначающего час: 三時 «три часа»."}},"時間":{"b":"時間 (じかん)","p":"n","m":{"az":"vaxt, saat","en":"time, hour","ru":"время, час"},"n":{"az":"食べる時間 = yemək vaxtı (feil isimdən əvvəl).","en":"食べる時間 = the time to eat.","ru":"食べる時間 = время еды."}},"暇":{"b":"暇 (ひま)","p":"an","m":{"az":"boş vaxt, boş, məşğul olmayan","en":"free time, free, unoccupied","ru":"свободное время, свободный"},"n":{"az":"な-sifət kimi 暇な人, isim kimi 暇がある işlənir.","en":"Used as a na-adjective in 暇な人 or as a noun in 暇がある.","ru":"Употребляется как na-прилагательное в 暇な人 или как существительное в 暇がある."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"最後":{"b":"最後 (さいご)","p":"n","m":{"az":"son, axır","en":"end, last","ru":"конец, последний"}},"服":{"b":"服 (ふく)","p":"n","m":{"az":"paltar","en":"clothes","ru":"одежда"}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"村":{"b":"村 (むら)","p":"n","m":{"az":"kənd","en":"village","ru":"деревня"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"止まる":{"b":"止まる (とまる)","p":"v","m":{"az":"dayanmaq","en":"to stop","ru":"останавливаться"},"n":{"az":"Təsirsizdir: バスが止まる; təsirli qarşılığı 止める-dir.","en":"Intransitive: バスが止まる; its transitive partner is 止める.","ru":"Непереходный: バスが止まる; переходная пара: 止める."}},"止める":{"b":"止める (とめる)","p":"v","m":{"az":"dayandırmaq; saxlamaq","en":"to stop something; to park","ru":"останавливать; парковать"},"n":{"az":"他動詞: 止める dayandırmaq, 止まる isə dayanmaq deməkdir.","en":"Transitive verb: 止める means to stop something, while 止まる means to stop.","ru":"Переходный глагол: 止める - останавливать, 止まる - останавливаться."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"泳ぐ":{"b":"泳ぐ (およぐ)","p":"v","m":{"az":"üzmək","en":"to swim","ru":"плавать"},"n":{"az":"泳ぎたくない - üzmək istəmirəm; 〜たい istək, 〜たくない isə inkar bildirir.","en":"泳ぎたくない means not wanting to swim; 〜たい expresses desire and 〜たくない negates it.","ru":"泳ぎたくない означает не хочу плавать; 〜たい выражает желание, а 〜たくない - отрицание."}},"海":{"b":"海 (うみ)","p":"n","m":{"az":"dəniz","en":"sea","ru":"море"}},"涙":{"b":"涙 (なみだ)","p":"n","m":{"az":"göz yaşı","en":"tear, tears","ru":"слеза, слёзы"}},"渡す":{"b":"渡す (わたす)","p":"v","m":{"az":"vermək, uzatmaq","en":"hand over, pass","ru":"передавать"},"n":{"az":"Keçişli feldir: 人に物を渡す “kiməsə nəsə vermək”; 渡る isə “qarşı tərəfə keçmək” deməkdir.","en":"A transitive verb: 人に物を渡す means “hand something to someone”; 渡る means “cross.”","ru":"Переходный глагол: 人に物を渡す «передать кому-то что-то»; 渡る означает «пересекать, переходить»."}},"物":{"b":"物 (もの)","p":"n","m":{"az":"şey; əşya","en":"thing; object","ru":"вещь; предмет"}},"犬":{"b":"犬 (いぬ)","p":"n","m":{"az":"it","en":"dog","ru":"собака"}},"用意":{"b":"用意 (ようい)","p":"n","m":{"az":"hazırlıq, hazırlama","en":"preparation","ru":"подготовка"},"n":{"az":"用意します hazırlamaq, 用意ができました hazır olmaq deməkdir.","en":"用意します means to prepare, and 用意ができました means preparation is complete.","ru":"用意します означает подготовить, а 用意ができました - всё готово."}},"男の子":{"b":"男の子 (おとこのこ)","p":"n","m":{"az":"oğlan","en":"boy","ru":"мальчик"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"目":{"b":"目 (め)","p":"n","m":{"az":"göz","en":"eye","ru":"глаз"}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"箱":{"b":"箱 (はこ)","p":"n","m":{"az":"qutu","en":"box","ru":"коробка"}},"紙":{"b":"紙 (かみ)","p":"n","m":{"az":"kağız","en":"paper","ru":"бумага"}},"結婚":{"b":"結婚 (けっこん)","p":"n","m":{"az":"evlilik","en":"marriage","ru":"брак; женитьба; замужество"},"n":{"az":"人と結婚する = biri ilə evlənmək.","en":"人と結婚する means to marry someone.","ru":"人と結婚する означает вступить с кем-то в брак."}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"自分":{"b":"自分 (じぶん)","p":"n","m":{"az":"öz, özü","en":"oneself","ru":"сам, свой"},"n":{"az":"自分の名前 = öz adı.","en":"自分の名前 = one's own name.","ru":"自分の名前 = своё имя."}},"自転車":{"b":"自転車 (じてんしゃ)","p":"n","m":{"az":"velosiped","en":"bicycle","ru":"велосипед"}},"船":{"b":"船 (ふね)","p":"n","m":{"az":"gəmi, qayıq","en":"ship, boat","ru":"корабль, лодка"}},"花":{"b":"花 (はな)","p":"n","m":{"az":"çiçək","en":"flower","ru":"цветок"}},"花屋":{"b":"花屋 (はなや)","p":"n","m":{"az":"gül dükanı, gülçü","en":"flower shop, florist","ru":"цветочный магазин, флорист"}},"落ちる":{"b":"落ちる (おちる)","p":"v","m":{"az":"düşmək, yıxılmaq","en":"to fall","ru":"падать"},"n":{"az":"落ちて来る = düşüb gəlmək (aşağı).","en":"落ちて来る = come falling down.","ru":"落ちて来る = упасть (сюда)."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見せる":{"b":"見せる (みせる)","p":"v","m":{"az":"göstərmək","en":"show","ru":"показывать"},"n":{"az":"人に物を見せる kiməsə nəyisə göstərmək quruluşudur.","en":"Use 人に物を見せる to show something to someone.","ru":"Конструкция 人に物を見せる означает показать что-либо кому-либо."}},"見つける":{"b":"見つける (みつける)","p":"v","m":{"az":"tapmaq; aşkar etmək","en":"find; discover","ru":"находить; обнаруживать"},"n":{"az":"Təsirli feldir; 見つかる tapılmaq deməkdir.","en":"A transitive verb; 見つかる means to be found.","ru":"Переходный глагол; 見つかる означает найтись."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"親切":{"b":"親切 (しんせつ)","p":"an","m":{"az":"mehriban, xeyirxah","en":"kind, helpful","ru":"добрый, отзывчивый"},"n":{"az":"な-sifətdir: 親切な人 = mehriban insan.","en":"A na-adjective: 親切な人 = kind person.","ru":"な-прилагательное: 親切な人 = добрый человек."}},"触る":{"b":"触る (さわる)","p":"v","m":{"az":"toxunmaq","en":"to touch","ru":"трогать; прикасаться"},"n":{"az":"Adətən N に触る şəklində işlənir: ボタンに触る.","en":"Usually takes に: ボタンに触る means to touch a button.","ru":"Обычно используется с に: ボタンに触る означает касаться кнопки."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"話":{"b":"話 (はなし)","p":"n","m":{"az":"söhbət, hekayə","en":"conversation, story","ru":"разговор, история"}},"話す":{"b":"話す (はなす)","p":"v","m":{"az":"danışmaq; söhbət etmək","en":"to speak; to talk","ru":"говорить; разговаривать"},"n":{"az":"Dil を, həmsöhbət と ilə göstərilir: 日本語を話す, 友達と話す.","en":"A language takes を and a conversation partner takes と: 日本語を話す, 友達と話す.","ru":"Язык обозначается через を, собеседник через と: 日本語を話す, 友達と話す."}},"読む":{"b":"読む (よむ)","p":"v","m":{"az":"oxumaq","en":"to read","ru":"читать"},"n":{"az":"て forması 読んで-dir: 読んでください oxuyun, zəhmət olmasa deməkdir.","en":"The て-form is 読んで: 読んでください means please read.","ru":"Форма на て: 読んで; 読んでください означает «прочитайте, пожалуйста»."}},"誰":{"b":"誰 (だれ)","p":"pr","m":{"az":"kim","en":"who","ru":"кто"},"n":{"az":"誰が = kim, 誰に = kimə, 誰の = kimin.","en":"誰が = who as subject; 誰に = to whom; 誰の = whose.","ru":"誰が = кто; 誰に = кому; 誰の = чей."}},"貧しい":{"b":"貧しい (まずしい)","p":"ai","m":{"az":"kasıb, yoxsul","en":"poor, impoverished","ru":"бедный, нищий"},"n":{"az":"い-sifətdir; maddi yoxsulluğu bildirir.","en":"An i-adjective usually describing material poverty.","ru":"Это i-прилагательное, обычно обозначающее материальную бедность."}},"買う":{"b":"買う (かう)","p":"v","m":{"az":"almaq; satın almaq","en":"buy","ru":"покупать"},"n":{"az":"て forması 買って olur.","en":"Its て-form is 買って.","ru":"Форма на て: 買って."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"遊ぶ":{"b":"遊ぶ (あそぶ)","p":"v","m":{"az":"oynamaq; əylənmək","en":"to play; to have fun","ru":"играть; развлекаться"},"n":{"az":"て-forması 遊んで-dir; 友達と遊ぶ = dostlarla oynamaq və ya vaxt keçirmək.","en":"Its て-form is 遊んで; 友達と遊ぶ means to play or spend time with friends.","ru":"て-форма: 遊んで; 友達と遊ぶ означает играть или проводить время с друзьями."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"遠く":{"b":"遠く (とおく)","p":"n","m":{"az":"uzaq yer, uzaqlıq","en":"faraway place, distance","ru":"далёкое место, даль"},"n":{"az":"遠い sifətinin formasıdır; 遠くに uzaqda deməkdir.","en":"Derived from 遠い; 遠くに means far away.","ru":"Образовано от 遠い; 遠くに означает далеко."}},"重い":{"b":"重い (おもい)","p":"ai","m":{"az":"ağır","en":"heavy","ru":"тяжёлый"},"n":{"az":"い sifətidir, 重くて bağlayıcı formadır: 重くて持てません.","en":"An i-adjective, with 重くて linking clauses: 重くて持てません means it is too heavy to carry.","ru":"Прилагательное на い, 重くて связывает части предложения: 重くて持てません - слишком тяжёлый, не могу нести."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"降る":{"b":"降る (ふる)","p":"v","m":{"az":"yağmaq","en":"fall as rain or snow","ru":"идти о дожде или снеге"},"n":{"az":"Yağıntı が ilə göstərilir: 雨が降る, 雪が降る.","en":"Precipitation takes が: 雨が降る, 雪が降る.","ru":"Осадки оформляются が: 雨が降る, 雪が降る."}},"雨":{"b":"雨 (あめ)","p":"n","m":{"az":"yağış","en":"rain","ru":"дождь"}},"電話":{"b":"電話 (でんわ)","p":"n","m":{"az":"telefon; telefon zəngi","en":"telephone; phone call","ru":"телефон; звонок"},"n":{"az":"電話する və 電話をかける telefonla zəng etmək deməkdir.","en":"電話する and 電話をかける both mean to make a phone call.","ru":"電話する и 電話をかける означают звонить по телефону."}},"電車":{"b":"電車 (でんしゃ)","p":"n","m":{"az":"elektrik qatarı","en":"electric train","ru":"электропоезд"}},"音":{"b":"音 (おと)","p":"n","m":{"az":"səs (əşya səsi)","en":"sound","ru":"звук"},"n":{"az":"音がする = səs gəlmək. İnsan səsi üçün 声.","en":"音がする = a sound is heard. Human voice: 声.","ru":"音がする = слышен звук. Голос человека – 声."}},"頼む":{"b":"頼む (たのむ)","p":"v","m":{"az":"xahiş etmək; sifariş vermək","en":"to request; to order","ru":"просить; заказывать"},"n":{"az":"頼みました keçmiş nəzakətli formadır.","en":"頼みました is the polite past form.","ru":"頼みました - вежливая форма прошедшего времени."}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"髪":{"b":"髪 (かみ)","p":"n","m":{"az":"saç","en":"hair","ru":"волосы"}},"魚":{"b":"魚 (さかな)","p":"n","m":{"az":"balıq","en":"fish","ru":"рыба"}}}};